          expect(testSeams.directorySessionEpoch).toBe(epoch + (retires ? 1 : 0));
          expect(artifactState(DOCUMENT, SPACE) === undefined).toBe(retires);
          if (scenario === "old-body-after-proof-replacement") {
            harness.bodies.push("{}");
