        expect(oracle(current, next), `fast-deep-equal oracle: ${row.case}`).toBe(row.resumes);
        expect(sameLeaseFieldsV1(current, next), `full-field relation: ${row.case}`).toBe(equal(row.patch, {}));
      }
    });

